
package com.example.orbitalcommand.model

/**
 * Identifies whether the simulated spacecraft is
 * exposed to sunlight or passing through Earth's shadow.
 */
enum class SolarExposure {
    SUNLIGHT,
    ECLIPSE
}

/**
 * Represents the simulated operational state of
 * a satellite's electrical power system.
 */
enum class PowerMode {
    NORMAL,
    LOW_POWER,
    SAFE_MODE,
    OFFLINE
}

/**
 * Represents a telemetry packet generated by a satellite.
 *
 * Measurements are associated with the simulation second
 * at which the packet was produced.
 *
 * Power measurements are generated by the local simulator
 * and do not represent physical spacecraft hardware.
 */
data class SatelliteTelemetry(
    val sampleSecond: Int,
    val altitudeKm: Double,
    val velocityKmS: Double,
    val batteryPercent: Double,
    val temperatureC: Double,
    val orbitAngleDegrees: Float,
    val solarExposure: SolarExposure = SolarExposure.SUNLIGHT,
    val solarGenerationWatts: Double = 0.0,
    val powerConsumptionWatts: Double = 0.0,
    val powerMode: PowerMode = PowerMode.NORMAL
)
